<!DOCTYPE html>
<html lang="pt-BR">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>@yield('title', 'Avaliação') — Instituto Alves Neves</title>
    <style>
        *{box-sizing:border-box}body{margin:0;background:#f8fafc;color:#1f2937;font-family:ui-sans-serif,system-ui,sans-serif}.top{width:100%;background:#fff;padding:10px 18px}.top-inner{max-width:920px;margin:0 auto;display:flex;justify-content:center}.top img{display:block;max-height:58px;max-width:min(100%,260px)}.survey-hero{position:relative;isolation:isolate;display:grid;grid-template-columns:minmax(0,1.65fr) minmax(110px,.35fr);gap:1.25rem;width:100%;overflow:hidden;padding:clamp(.8rem,2vw,1.4rem);border:1px solid rgba(245,158,11,.3);border-radius:1rem;background:linear-gradient(130deg,#fffdf7 0%,#fff7df 52%,#f8edff 100%);box-shadow:0 10px 28px rgba(120,86,24,.1)}.hero-glow{position:absolute;z-index:-1;border-radius:999px;filter:blur(4px);opacity:.75}.hero-glow-one{width:180px;height:180px;right:-55px;top:-85px;background:rgba(245,158,11,.24)}.hero-glow-two{width:130px;height:130px;right:18%;bottom:-90px;background:rgba(124,58,237,.16)}.survey-hero-content{align-self:center;max-width:680px}.survey-overline{display:inline-block;margin-bottom:.45rem;color:#a45f08;font-size:.65rem;font-weight:850;letter-spacing:.1em;text-transform:uppercase}.survey-hero h1{margin:0;color:#172033;font-size:clamp(1.3rem,2.4vw,2rem);font-weight:900;letter-spacing:-.04em;line-height:1.08}.survey-hero p{margin:.45rem 0 0;color:#525d70;font-size:clamp(.8rem,1.3vw,.92rem);line-height:1.5}.survey-hero-mark{align-self:center;justify-self:end;display:flex;width:92px;height:92px;flex-direction:column;align-items:center;justify-content:center;border:1px solid rgba(255,255,255,.8);border-radius:50%;background:rgba(255,255,255,.54);box-shadow:inset 0 0 0 7px rgba(255,255,255,.24),0 10px 24px rgba(127,83,13,.12);backdrop-filter:blur(10px);text-align:center}.survey-hero-mark img{display:block;width:39px;height:39px;margin-bottom:.1rem;object-fit:contain}.survey-hero-mark small{max-width:72px;color:#6f5c42;font-size:.48rem;font-weight:700;line-height:1.15}.wrap{max-width:920px;margin:22px auto;padding:0 18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:10px;box-shadow:0 4px 15px rgba(15,23,42,.14);padding:30px}.page-title{text-align:center;margin:0 0 10px;font-size:clamp(1.65rem,4vw,2.25rem);font-weight:900;text-transform:uppercase}.introduction{text-align:center;max-width:720px;margin:0 auto 28px;color:#64748b;line-height:1.6}.muted{color:#64748b}.question{margin:0 0 24px;padding:22px 24px;border:1px solid #e5e7eb!important;border-radius:7px;box-shadow:0 3px 12px rgba(15,23,42,.16);text-align:center}.question legend{float:left;width:100%;padding:0 10px;margin:0 0 14px;text-align:center}.required-mark{color:#dc2626;font-weight:900}.question legend+*{clear:both}.options{display:grid;grid-template-columns:repeat(auto-fit,minmax(90px,1fr));gap:12px;margin-top:12px}.option{position:relative;display:block}.option input{position:absolute;opacity:0;pointer-events:none}.option span{display:flex;min-height:104px;align-items:center;justify-content:center;flex-direction:column;gap:8px;border:2px solid transparent;border-radius:7px;padding:10px 6px;cursor:pointer;font-weight:500;text-align:center;transition:.16s ease}.option span:hover{background:#fff;border-color:#d1d5db;box-shadow:0 3px 10px rgba(15,23,42,.22);transform:translateY(-1px)}.option input:focus-visible+span{outline:3px solid rgba(245,158,11,.35)}.option input:checked+span{border-color:#9ca3af;background:#fff;box-shadow:0 3px 10px rgba(15,23,42,.28);color:#1f2937}.emoji{font-size:3.25rem;line-height:1}.form-footer{text-align:center}.btn{border:0;border-radius:4px;background:#292524;color:#fff;font-weight:700;padding:14px 28px;cursor:pointer;text-decoration:none;display:inline-block}.btn:hover{background:#44403c}.alert{color:#dc2626;text-align:center;padding:5px 16px;margin:6px 0 12px}.success-icon{width:70px;height:70px;margin:0 auto 20px;border-radius:50%;display:grid;place-items:center;background:#ecfdf5;color:#059669;font-size:2.5rem;font-weight:900}.redirect{margin-top:24px;color:#64748b}.redirect a{color:#b45309;font-weight:700}@media(max-width:700px){.survey-hero{grid-template-columns:1fr}.survey-hero-mark{display:none}}@media(max-width:640px){.top img{max-height:52px}.card{padding:20px 14px}.wrap{margin:14px auto;padding:0 12px}.question{padding:18px 10px}.options{grid-template-columns:repeat(3,1fr);gap:5px}.option span{min-height:92px;font-size:.8rem;padding:7px 2px}.emoji{font-size:2.6rem}}
        /* Usa exatamente a mesma largura visual do conteúdo da pesquisa. */
        .top{padding-left:0;padding-right:0}
        .top-inner{width:calc(100% - 36px);max-width:884px}
        @media(max-width:640px){.top-inner{width:calc(100% - 24px)}}
        .survey-list-card{padding:1.35rem}.survey-list-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:1rem;color:#667085;font-size:.72rem;font-weight:850;letter-spacing:.07em;text-transform:uppercase}.survey-list-heading strong{display:grid;width:28px;height:28px;place-items:center;border-radius:50%;background:#fff7df;color:#a45f08}.public-survey-item{display:grid;grid-template-columns:44px minmax(0,1fr) auto;align-items:center;gap:1rem;padding:1.15rem;border:1px solid #e8eaf0;border-radius:.9rem;background:linear-gradient(110deg,#fff,#fffdf8);box-shadow:0 5px 18px rgba(28,39,60,.05);transition:transform .18s,box-shadow .18s,border-color .18s}.public-survey-item+.public-survey-item{margin-top:.8rem}.public-survey-item:hover{transform:translateY(-2px);border-color:rgba(245,158,11,.4);box-shadow:0 12px 28px rgba(28,39,60,.09)}.public-survey-icon{display:grid;width:44px;height:44px;place-items:center;border-radius:.75rem;background:#fff7df;color:#d97706;font-weight:900}.public-survey-copy h2{margin:0;color:#172033;font-size:1rem}.public-survey-copy p{margin:.35rem 0;font-size:.78rem;line-height:1.5}.public-survey-copy small{color:#98a2b3;font-size:.68rem}.public-survey-item .btn{white-space:nowrap}.survey-empty{padding:2.5rem;text-align:center}.survey-empty b{display:grid;width:54px;height:54px;margin:0 auto 1rem;place-items:center;border-radius:50%;background:#ecfdf3;color:#059669;font-size:1.4rem}.survey-empty h2{margin:0}.survey-empty p{color:#667085}@media(max-width:640px){.public-survey-item{grid-template-columns:40px 1fr}.public-survey-item .btn{grid-column:1/-1;text-align:center}}
        .options:has(.numeric-scale){display:block}.numeric-scale{display:grid;grid-template-columns:repeat(11,minmax(44px,1fr));gap:9px;width:100%;margin-top:.25rem}.numeric-option{position:relative;display:flex;justify-content:center}.numeric-option input{position:absolute;opacity:0;pointer-events:none}.numeric-option span{display:grid;width:52px;height:52px;place-items:center;border:2px solid #aeb8c2;border-radius:50%;background:#fff;color:#64748b;box-shadow:0 2px 5px rgba(15,23,42,.08);font-size:1.1rem;font-weight:650;cursor:pointer;transition:transform .16s,border-color .16s,background .16s,color .16s,box-shadow .16s}.numeric-option span:hover{transform:translateY(-2px) scale(1.05);border-color:#64748b;box-shadow:0 5px 12px rgba(15,23,42,.18)}.numeric-option input:focus-visible+span{outline:3px solid rgba(59,130,246,.3);outline-offset:2px}.numeric-option input:checked+span{border-color:#475569;background:#475569;color:#fff;box-shadow:0 4px 12px rgba(30,41,59,.32);font-weight:850}.numeric-colors{display:grid;grid-column:1/-1;grid-template-columns:7fr 2fr 2fr;gap:7px;margin-top:-1px}.numeric-colors i{display:block;height:6px;border-radius:999px}.numeric-colors i:nth-child(1){background:#e83f4f}.numeric-colors i:nth-child(2){background:#f1d510}.numeric-colors i:nth-child(3){background:#71dc8f}@media(max-width:700px){.numeric-scale{grid-template-columns:repeat(11,44px);gap:7px;overflow-x:auto;padding:3px 2px 10px;scrollbar-width:thin}.numeric-option span{width:42px;height:42px;font-size:.95rem}.numeric-colors{min-width:554px}}
    </style>
</head>
<body>
<header class="top"><div class="top-inner">@hasSection('survey-hero') @yield('survey-hero') @else <img src="{{ asset('images/logo.png') }}" alt="Instituto Alves Neves"> @endif</div></header>
<main class="wrap">@yield('content')</main>
</body>
</html>
